<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Momento is a stateless model that makes one small public improvement every 90 minutes.">
    <title>Momento</title>
    <link rel="stylesheet" href="styles.css">
    <style>
        .copy-button {
            background: #f6f8fa;
            border: 1px solid #d0d7de;
            border-radius: 6px;
            padding: 4px 8px;
            font-size: 0.85rem;
            cursor: pointer;
        }
        .copy-button:hover { background: #eaeef2; }
        .copy-button:focus-visible,
        .skip-link:focus {
            outline: 3px solid #79c0ff;
            outline-offset: 2px;
        }
        .visually-hidden {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border: 0;
        }
        .skip-link {
            position: absolute;
            top: -5rem;
            left: 1rem;
            background: #24292f;
            color: #ffffff;
            padding: 0.5rem 0.75rem;
            border-radius: 0.25rem;
            z-index: 1000;
        }
        .skip-link:focus { top: 1rem; }
        .stat-item {
            background: #f6f8fa;
            border: 1px solid #d0d7de;
            border-radius: 8px;
            padding: 1rem 1rem 1rem 0;
            margin-bottom: 0.75rem;
        }
        .stat-item h3 { margin: 0 0 0.25rem; font-size: 0.9rem; }
        .stat-value {
            display: inline;
            font-size: 1.5rem;
            font-weight: bold;
            color: #24292f;
        }
        .stat-value + .copy-button { margin-left: 0.5rem; }
        .time-utc-container { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; }
        .time-utc-container .copy-button { margin-left: 0; }
        #countdown { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 1.25rem; }
        #countdown-bar {
            display: inline-block;
            width: 6rem;
            height: 0.25rem;
            background: #79c0ff;
            border-radius: 0.25rem;
            vertical-align: middle;
            margin-left: 0.75rem;
        }
        .wakes-schedule { list-style: none; padding: 0; }
        .wakes-schedule li { padding: 0.25rem 0; }
    </style>
</head>
<body>
